def dense(a):
    return a.toarray()

docs = ["The quick brown fox jumps over the lazy dog.", "Never jump over the lazy dog quickly!",
        "A fox, a dog and a café: naïve résumé.", "the the THE dog dog fox", "Brown foxes are quick; dogs are lazy."]
cv = CountVectorizer()
check(close(dense(cv.fit_transform(docs)), cv_X), "cv X"); check(cv.get_feature_names_out() == cv_names, "cv names")
cv2 = CountVectorizer(ngram_range=(1, 2), stop_words="english", min_df=2)
check(close(dense(cv2.fit_transform(docs)), cv2_X), "cv2 X"); check(cv2.get_feature_names_out() == cv2_names, "cv2 names")
cv3 = CountVectorizer(max_features=5, binary=True, max_df=0.8)
check(close(dense(cv3.fit_transform(docs)), cv3_X), "cv3 X"); check(cv3.get_feature_names_out() == cv3_names, "cv3 names")
cv4 = CountVectorizer(analyzer="char", ngram_range=(2, 3), strip_accents="unicode", min_df=4)
check(close(dense(cv4.fit_transform(docs)), cv4_X), "cv4 X"); check(cv4.get_feature_names_out() == cv4_names, "cv4 names")
cv5 = CountVectorizer(analyzer="char_wb", ngram_range=(2, 3), strip_accents="ascii", min_df=3)
