D = [{"city": "Dubai", "temp": "33.0"}, {"city": "London", "temp": "12.0", "rain": "1.0"}, {"city": "Paris", "temp": "18.5"}]
def tod(d: Dict[str, str]):
    out = Dict[str, Union[str, float]]()
    for k, v in d.items():
        if k == "city":
            out[k] = Union[str, float](v)
        else:
            out[k] = Union[str, float](float(v))
    return out
DD = [tod(d) for d in D]
dv = DictVectorizer(sparse=False)
check(close(dv.fit_transform(DD), dv_X), "dv X"); check(dv.get_feature_names_out() == dv_names, "dv names")
check(close(dv.transform([tod({"city": "Paris", "wind": "3.0", "temp": "1.0"})]), dv_T), "dv T")
dv2 = DictVectorizer(sort=False)
check(close(dense(dv2.fit_transform(DD)), dv2_X), "dv2 X"); check(dv2.get_feature_names_out() == dv2_names, "dv2 names")
